from typing import List


def factorize(n: int) -> List[int]:
    """Return list of prime factors of n in order from smallest to largest.
    Each factor is listed with its multiplicity.
    Input n is guaranteed to be a positive integer.
    """
    factors = []
    # Handle negative numbers by taking absolute value
    if n < 0:
        n = -n
        factors = []
        for i in range(2, int(n**0.5) + 1):
            while n % i == 0:
                factors.append(i)
                n //= i
        # If n > 1, it's still prime
        if n > 1:
            factors.append(n)
    else:
        for i in range(2, int(n**0.5) + 1):
            while n % i == 0:
                factors.append(i)
                n //= i
        if n > 1:
            factors.append(n)
    return factors
```

